import type { TeachingCheck, TeachingLesson, TeachingTransfer } from "../teaching";

const math = String.raw;

function check(
  prompt: string,
  choices: string[],
  correct: number,
  feedback: string[],
  prerequisite: string,
): TeachingCheck {
  return { prompt, choices, correct, feedback, prerequisite };
}

function transfer(
  prompt: string,
  promptFormula: string,
  answer: number,
  solution: string,
  remediation: string,
): TeachingTransfer {
  return { prompt, promptFormula, answer, solution, remediation, signFeedback: remediation };
}

function lesson(
  strategy: string,
  goal: string,
  plain: string,
  understanding: TeachingCheck,
  formula: string,
  detail: string,
  practice: TeachingTransfer,
): TeachingLesson {
  return {
    strategy,
    target: goal,
    prerequisites: [understanding.prerequisite],
    solution: formula,
    steps: [{ id: "reason", goal, plain, formula, detail, check: understanding, transfer: practice }],
  };
}

